#include <stdio.h>
#include <string.h>
int main() {
    char s[1000]; if (scanf("%s", s) != 1) return 0;
    int len = strlen(s);
    for (int i = 0; i < len;) {
        char c = s[i]; int cnt = 0;
        while (i < len && s[i] == c) { cnt++; i++; }
        printf("%c%d", c, cnt);
    }
    putchar('\n');
    return 0;
}

