    const s = fs.readFileSync(0, "utf-8").trim();
    if (!s) return;
    let res = "", curC = s[0], cnt = 1;
    for (let i = 1; i < s.length; i++) {
        if (s[i] === curC) cnt++;
        else { res += curC + cnt; curC = s[i]; cnt = 1; }
    }
    res += curC + cnt;
    console.log(res);
}
main();

